return [
  {
    "type": "bar",
    "data": {
      "labels": $input.first().json.adsetNameValue,
      "datasets": [
        {
          "type": "bar",
          "label": $input.first().json.impressionsKey,
          "borderColor": "rgb(54, 162, 235)",
          "borderWidth": 2,
          "fill": false,
          "data": $input.first().json.impressionsValue
        },
        {
          "type": "bar",
          "label": $input.first().json.reachKey,
          "backgroundColor": "rgb(255, 99, 132)",
          "data": $input.first().json.reachValue,
          "borderColor": "white",
          "borderWidth": 2
        },
        {
          "type": "bar",
          "label": $input.first().json.linkClicksKey,
          "backgroundColor": "rgb(75, 192, 192)",
          "data": $input.first().json.linkClicksValue,
          "borderColor": "white",
          "borderWidth": 2
        }        
      ]
    },
    "options": {
      "responsive": true,
      "title": {
        "display": true,
        "text": "ADSET LEVEL " + $input.first().json.impressionsKey.toUpperCase() + " - " + $input.first().json.reachKey.toLocaleUpperCase() + " - " + $input.first().json.linkClicksKey.toLocaleUpperCase() + " COMPARISON CHART"
      },
      "tooltips": {
        "mode": "index",
        "intersect": true
      }
    }
  }
];

const plot = JSON.stringify($input.first().json);

return {
  plot: Buffer.from(plot).toString('base64')
};

